function wrap_line(buf, off, start, width) {
let n = 0;
let cut = 0;
n = 0;
while (SC_STR[off + start + n] != 0 && n < width) {
buf[n] = SC_STR[off + start + n];
n = n + 1;
}
cut = n;
if (SC_STR[off + start + n] != 0) {
while (cut > 0 && buf[cut - 1] != 32) cut = (cut - 1);
if (cut == 0) cut = n;
}
buf[cut] = 0;
return cut;
}
